// Задание 7: Реле уровня задымления
const int mq2Pin = A5;
const int relayPin = 11;
const int threshold = 700;

void setup() {
  Serial.begin(9600);
  pinMode(relayPin, OUTPUT);
  digitalWrite(relayPin, LOW);
}

void loop() {
  int smokeLevel = analogRead(mq2Pin);
  Serial.print("Уровень задымления: ");
  Serial.println(smokeLevel);

  if (smokeLevel > threshold) {
    digitalWrite(relayPin, HIGH);
    Serial.println("ВНИМАНИЕ: Задымление! Реле ВКЛ.");
  } else {
    digitalWrite(relayPin, LOW);
  }
  delay(1000);
}
